import {decode31015,commandPlan31015} from './zsc31015.mjs';
// Signature is generated by the IC; all other EEPROM bytes must match.
export function same31015(a,b){decode31015(a);decode31015(b);return a.every((v,i)=>i===14||v===b[i])}
export function prepareChanges31015(original,{afeGainCode,adcOffset}){
 const d=decode31015(original);if(d.locked)throw Error('EEPROM gesperrt.');if(adcOffset&4)throw Error('Negative Digitalgain-Variante noch nicht verifiziert.');
 return {afeGainCode,adcOffset,outputMode:0,gainB:0x800,offsetB:0,gainT:0x80,offsetTCode:0,tco:0,tcg:0,tcConfig:0,sot:0,sotConfig:1,tsetl:0,clipHigh:127,clipLow:0};
}
const keys=['afeGainCode','adcOffset','outputMode','updateRate','gainB','offsetB','gainT','offsetTCode','tco','tcg','tcConfig','sot','sotConfig','tsetl','clipHigh','clipLow'];
export function restoreChanges31015(original){const d=decode31015(original);return Object.fromEntries(keys.map(k=>[k,d[k]]))}
export function restorePlan31015(current,original){
 const changes=restoreChanges31015(original),plan=commandPlan31015(current,changes);
 if(!same31015(plan.expected,original))throw Error('Geschützte EEPROM-Felder stimmen nicht mit dem Original-Backup überein. Keine Schreibvorgänge.');
 return changes;
}
export async function programConfig31015(driver,before,changes){
 if(driver.model!=='zsc31015'||driver.mode!=='cm')throw Error('ZSC31015 Command Mode erforderlich.');
 const plan=commandPlan31015(before,changes),actual=await driver.readVerified();
 if(!same31015(before,actual))throw Error('EEPROM seit Vorschau verändert; neu auslesen.');
 for(const bytes of plan.commands){
  const cmd='rw_00002'+bytes.map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase();
  const ack=await driver.command(cmd);
  if(ack.toUpperCase()!=='A5')throw Error('Schreiben nicht bestätigt. EEPROM kann teilweise geändert sein. Original-Backup behalten; nicht automatisch wiederholen.');
 }
 const after=await driver.readVerified();
 if(!same31015(after,plan.expected))throw Error('EEPROM-Rücklesekontrolle fehlgeschlagen. Original-Backup behalten.');
 return after;
}
